def reraise(errors, into):
    """Reraises errors by passing them into the into callback.

    Can be used as a decorator or a context manager::

        @reraise(ValueError, lambda e: TypeError(str(e)))
        def my_func():
            # ...

        with reraise(ValueError, lambda e: TypeError(str(e))):
            # ...
    """
    errors = _ensure_exceptable(errors)

    class ReraiseContext:
        def __enter__(self):
            return self

        def __exit__(self, exctype, excinst, exctb):
            if exctype is not None and issubclass(exctype, errors):
                raise into(excinst)
            return False

    ctx = ReraiseContext()

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except errors as e:
                raise into(e)
        return wrapper

    return decorator


def api_call(errors, fallback=None):
    """Decorator/context manager for API calls with error handling.

    Converts specified errors into a different exception or returns fallback value.

    Examples::

        @api_call(requests.RequestException, fallback=None)
        def fetch_data(url):
            # ...

        with api_call(requests.RequestException, fallback={}):
            # ...
    """
    if fallback is not None:
        into = lambda e: fallback
    else:
        into = lambda e: raise_from(type(e), e)

    return reraise(errors, into)


